  document.querySelectorAll('.drop-before,.drop-after,.drop-left,.drop-right').forEach(el=>el.classList.remove('drop-before','drop-after','drop-left','drop-right'));
  const target=document.elementFromPoint(ev.clientX,ev.clientY)?.closest('[data-drop]');source.target=null;
  if(!target||target.dataset.topic!==source.topic||target.dataset.order!==source.order)return;
  const rect=target.getBoundingClientRect(),grid=target.closest('.selection-list'),horizontal=grid&&getComputedStyle(grid).gridTemplateColumns.split(' ').length>1,after=horizontal?ev.clientX>=rect.left+rect.width/2:ev.clientY>=rect.top+rect.height/2;target.classList.add(horizontal?(after?'drop-right':'drop-left'):(after?'drop-after':'drop-before'));source.target={...target.dataset,after};
  const shelf=target.closest('.draft-shelf,.draft-paragraphs');if(shelf){const r=shelf.getBoundingClientRect();if(ev.clientY<r.top+45)shelf.scrollTop-=24;else if(ev.clientY>r.bottom-45)shelf.scrollTop+=24;}else if(ev.clientY<60)window.scrollBy(0,-24);else if(ev.clientY>innerHeight-60)window.scrollBy(0,24);
